@pytest.mark.integration
class TestExtractionSchema:
    """All extractions must conform to the expected JSON schema regardless of contract."""

    def test_aetna_required_fields(self, aetna_metrics):
        for m in aetna_metrics:
            assert "metric_name" in m, f"Missing metric_name: {m}"
            assert "target_operator" in m, f"Missing target_operator: {m}"

    def test_meridian_required_fields(self, meridian_metrics):
        for m in meridian_metrics:
            assert "metric_name" in m, f"Missing metric_name: {m}"
            assert "target_operator" in m, f"Missing target_operator: {m}"
